SELECT 'ALE-UTIL-008-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-UTIL-008'), 3, 'System Sizing & Calculations', 'Building Utilities / MEPF', 'fact'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Water Supply Sizing: Peak demand calculation; Pressure requirement at highest fixture; Pipe sizing from demand and velocity limits; Pressure drop calculations", "type": "fact"}, {"text": "Drainage Sizing: DFU method for waste pipe sizing; Stack diameter based on height and load; Vent sizing by drainage load and height", "type": "fact"}, {"text": "Electrical Load Calculation: Connected load vs. demand load; Demand factor application; Future expansion allowance; Service entrance sizing", "type": "fact"}, {"text": "HVAC Cooling Load: Sensible cooling load: external (solar, transmission), internal (lights, people, equipment); Latent cooling load (moisture removal); Peak hours by season; Ton calculation for sizing", "type": "fact"}, {"text": "Duct Sizing: Velocity method (typically 400-600 ft/min); Equal friction method; Duct area calculation from flow and velocity", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-util-008-03'
