-- ── Step 3: Update wiki_items on existing nodes ─────────────────────
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Water Sources: Surface sources (lakes, streams, rivers, reservoirs, roof runoff); Underground sources (shallow wells, deep wells, artesian wells, springs, land springs)", "type": "fact"}, {"text": "Water Quality Parameters: Alkalinity: caused by bicarbonate/carbonate/hydroxide components; Hardness: inhibits soap cleaning; pH range 5.5-14 (neutral pH=7); Testing protocols per PH codes", "type": "fact"}, {"text": "Water Distribution Methods: Gravitational distribution: impounded reservoir with no pumping; Pumped distribution: filtered & chlorinated water from mains; Ring main distribution: isolated sections with minimal disruption", "type": "fact"}, {"text": "Water Contamination Standards: River source typical 61,000 microbes/L; Impounding reservoir 1500; Primary filter 100; Secondary filter 50; Chlorination reduces to 0; Distribution mains must maintain 0 contamination", "type": "fact"}, {"text": "Chlorination Process: Destroys bacterial microbes before distribution to water mains; Essential step for potable water treatment", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-001-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Water Closets: Receives human excrement and discharges through waste pipe; Types: floor-mounted, wall-hung, one-piece, two-piece, round bowl, elongated; Flush operations: flush tank (9.5L/2.5gal), flush valve (14.2L/3.75gal), siphon jet, siphon vortex; NPCP Sec 401 specifies required bowl type for public use (elongated)", "type": "fact"}, {"text": "Bidets: Sealed sanitary appliance for washing private parts; Connected to water supply and drain", "type": "fact"}, {"text": "Urinals: Types: stall urinal (curved console fitted to wall, drainage channel), slab urinal (sheet fitted to wall, collected discharge in floor channel), bowl urinal (individual wall-mounted), waterless urinal (BlueSeal liquid barrier, 3oz replenish per 1500 uses)", "type": "fact"}, {"text": "Lavatories: Basin with water supply and drainage piping; Types: wall-hung, pedestal, counter-top", "type": "fact"}, {"text": "Sinks: Kitchen sink: vitreous china/stainless steel; Service sinks (janitor rooms): for filling/emptying vessels; Belfast sink style", "type": "fact"}, {"text": "Bathtubs: Large vessel for full-body immersion; Types: footbath, hip bath, jacuzzi, plunge bath, treatment bath, whirlpool bath; Whirlpool bath requires removable panel access to pump/circulation, self-draining piping (NPCP Sec 411)", "type": "fact"}, {"text": "Showers: Sanitary installation with controllable spray/jet of water for washing and cleaning", "type": "fact"}, {"text": "Drinking Fountains: Public appliance for drinking water; Found in schools, institutions; Basin with jet of clean water", "type": "fact"}, {"text": "Washing Fountains: Ablution fountain (albution fountain); Large circular/polygonal communal washbasin for multiple simultaneous users", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-001-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Fixture Unit Concept: Essential design criteria: (1) number of fixtures, (2) number of fixture units, (3) supply main flow rate, (4) water pressure of highest fixture", "type": "fact"}, {"text": "Water Fixture Units (WFU): Quantifies water demand per fixture; Used for supply piping design", "type": "fact"}, {"text": "Drainage Fixture Units (DFU): Quantifies waste discharge per fixture; Standard fixture = 1 DFU; Used for waste/vent pipe sizing", "type": "fact"}, {"text": "Philippine Code Requirements: NPCP Sec 401: Minimum fixtures per building type; Bathroom unit for disabled persons: 2000mm L x 1500mm W with grab bars, 900mm clear space", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-001-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Trap Function: Device at drainage outlet filled with water to prevent foul air passage from sewer back into building; Protects against siphonage and back-pressure", "type": "fact"}, {"text": "Trap Types: P-trap (most common, 90° elbow); S-trap (forbidden in modern code); U-trap; Bottle trap; Swivel trap; Integral trap; Shower trap; Drum trap; Low-level bath trap; Straight-through trap", "type": "fact"}, {"text": "Vent Piping: Each fixture trap must be protected against siphonage & back-pressure by properly placed vent pipe (NPCP Sec 1002); Vent prevents trap seal loss", "type": "fact"}, {"text": "Trap Seal Protection: Minimum trap depth: adequate water seal; Maximum 1.5m to vent or main stack; Prevention of siphonage, evaporation, and back-pressure", "type": "fact"}, {"text": "Common Trap Configurations: Single trap (common floor plan): single fixture single trap; Double trap: fixtures in series share trap (forbidden in modern codes)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-001-04';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Copper Piping: Corrosion-resistant, called ''copper tubing'' due to thin wall; Fittings: union, reducer, 90° elbow, reducing elbow, 45° elbow, T-fittings, reducing T-fittings, caps; Connection types: threaded adapters, drop-ear elbows, supplies", "type": "fact"}, {"text": "Plastic Piping: Lightweight, cheaper than copper; No corrosion; Does not present corrosion problems; Types: PE (polyethylene), ABS, PVC, CPVC, PB (polybutylene); Fittings connected by solvent cement or fusion machine", "type": "fact"}, {"text": "Steel Piping: Available in galvanized/black/extra heavy types; Most common; Connections: threaded; Requires more labor; Fittings: tee, union/bushing, coupling, reducer, plug, nipple, cap, elbow, 45° elbow", "type": "fact"}, {"text": "Pipe Slope Gradient: Minimum slope 1:50 (1 inch per 50 feet horizontal run); Ensures gravity drainage; Critical for proper flow", "type": "fact"}, {"text": "Thermal Expansion: Hot water piping subject to deformation; Expansion loops, protective covers, and section controls required; Typical expansion: 1/2\" expansion loop per 10m of horizontal run", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-001-05';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Comfort Definition: Balance of pleasant body feeling from surroundings; Four components: (1) temperature, (2) humidity, (3) air movement, (4) air cleanliness", "type": "fact"}, {"text": "Heat Transfer Methods: (1) Conduction: direct contact; (2) Convection: air circulation movement; (3) Radiation: infrared energy transfer; (4) Evaporation: perspiration cooling", "type": "fact"}, {"text": "Evaporative Cooling: Fourth way human body loses heat through water vapor (perspiration) evaporation", "type": "fact"}, {"text": "Heat Load Calculation: Every kilowatt of electrical energy in use produces 3413 Btu/h; Surface facing sun receives 300 Btu/h on clear day; Individual gives ~400 Btu/h in 23.3°C room", "type": "fact"}, {"text": "Cooling Conversion: 1 ton refrigeration = 3.517 kW = 12,000 BTU/hr", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-002-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Duct-free Type (Mini-split): Packaged equipment with all components in one cabinet; Window room AC units (WRAC); Packaged Terminal AC (PTAC); Split-system equipment with remote evaporator and condenser with interconnecting refrigerant lines", "type": "fact"}, {"text": "Ducted Type (Centralized): Central chiller with air-handling units (AHU); Duct system for supply/return; Plenum radial, extended plenum, reducing extended plenum, perimeter loop systems with feeder/loop ducts in slab", "type": "fact"}, {"text": "Air-Handling Unit (AHU): In all-air system, circulates air through filter and hot/cold water coils for conditioning", "type": "fact"}, {"text": "Window Room AC (WRAC): 1.00 hp: 20 sq.m; 1.50 hp: 24 sq.m; 2.00 hp: 32 sq.m; 2.50 hp: 38 sq.m; 4.00 hp: 50 sq.m", "type": "fact"}, {"text": "Ceiling Mounted AC: 3.00 hp: 45 sq.m; 4.00 hp: 50 sq.m; 6.00 hp: 80 sq.m", "type": "fact"}, {"text": "Ceiling Cassette AC: 3.00 hp: 45 sq.m; 5.00 hp: 85 sq.m", "type": "fact"}, {"text": "Floor Mounted AC: 3.00 hp: 45 sq.m; 5.00 hp: 80 sq.m", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-002-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Evaporator: Absorbs heat into the system; Low-temperature component where refrigerant evaporates from liquid to gas", "type": "fact"}, {"text": "Compressor: Heart of refrigeration system; Pumps and pressurizes refrigerant vapor", "type": "fact"}, {"text": "Condenser: Rejects both sensible (measurable) and latent (hidden) heat from refrigeration system; High-temperature component", "type": "fact"}, {"text": "Metering Device: Regulates refrigerant flow through system", "type": "fact"}, {"text": "Dehumidifying Process: Air dehumidifying means removing moisture; Frequently desirable in refrigeration systems", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-002-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Refrigerant Definition: Substance that picks up latent heat when substance evaporates from liquid to gas", "type": "fact"}, {"text": "Common Refrigerants: Sulfur dioxide: colorless but toxic liquid/gas, not safe (now prohibited); Methyl chloride: good refrigerant but flammable; Ammonia: very toxic & flammable gas; Carbon dioxide: very harmful in large concentration & without oxygen presence; Freon: dominant for residential AC (non-flammable, low toxicity, no thermal effect to metals)", "type": "fact"}, {"text": "Freon Properties: Reason for tremendous growth in residential AC; Not flammable; Low toxicity; Can cause frostbite on skin contact; No thermal effect to most metals", "type": "fact"}, {"text": "Environmental Impact: Montreal Protocol (1987): total phase-out of freon & other chlorofluorocarbons (CFC); 1996: non-production in developing countries; Freons major contributor to ozone depletion", "type": "fact"}, {"text": "Freon Alternatives: Generation AZ 20; SUVA 410A; Puron", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-002-04';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Electricity Definition: Form of energy resulting from existence of charged subatomic particles (electron and proton)", "type": "fact"}, {"text": "Electron Theory: Elements of atom: electron (negative charge), proton (positive charge), nucleus; Free electrons enable electrical flow", "type": "fact"}, {"text": "Conductors: Best: gold, silver; Good: copper, aluminum; Fair: steel, iron, other metals, salt water", "type": "fact"}, {"text": "Insulators: Good: glass, porcelain, dry wood, paper, plastic, rubber, water (pure); Fair: water (impure); Insulating material called dielectric", "type": "fact"}, {"text": "Insulated Conductors: Wire: pliable metallic strand or twisted assembly of strands, insulated with dielectric material; Cable: single insulated conductor or bound/sheathed combinations insulated from one another", "type": "fact"}, {"text": "Insulation Types: Thermoplastic: polycarbonate, polyethylene, polypropylene, polystyrene, polyvinyl & vinyl; Thermosetting: polyester, polyurethane, epoxy, melamine, phenolic", "type": "fact"}, {"text": "Wire Insulation Codes: Multiple insulation types with temperature and location ratings; Fire resistance, moisture resistance, mechanical strength specifications", "type": "fact"}, {"text": "OHM''s Law: Voltage (volts) = current (amperes) × resistance (ohms); V = IR; E = I × R; I = E/R; R = E/I", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-003-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Series Circuits: Arrangement of component in electric circuit where same current flows through each component in turn without branching", "type": "fact"}, {"text": "Parallel Circuits: Arrangement where all positive terminals connected to one conductor and all negative terminal to second conductor; Same voltage applied to each component", "type": "fact"}, {"text": "Circuit Classification by NEC: (1) General Purpose Branch Circuit: supplies outlets for lighting and appliances including convenience receptacles; (2) Appliance Branch Circuit: supplies outlets intended for feeding appliances; (3) Individual Branch Circuit: designed to supply single specific item", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-003-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Residential Appliance Watts: Range: 4,500W; Air Con (3/hp): 1,200W; Central Air Con: 5,000W; Range Tops: 6,000W; Dryer: 5,000W; Dishwasher: 1,200W; Microwave: 1,000W; Refrigerator: 300W; Freezer: 350W; Washing Machine: 1,200W; Hand Iron: 1,650W; Water Heater (MP): 4,500W; Water Heater (SP): 1,400W; Television: 300W; Audio Centre: 350W; PC & Peripherals: 1,000W; Pumps: 1,200W", "type": "fact"}, {"text": "Circuit Breaker Ratings: Range: 30AT; Air Con (3/hp): 30AT; Central Air Con: 40A; Range Tops: 30A; Dryer: 30A; Dishwasher: 20A; Microwave: 20A; Refrigerator: 20A; Freezer: 20A; Washing Machine: 20A; Hand Iron: 20A; Water Heater (MP): 30AT; Water Heater (SP): 20A; Television: 20A; Audio Centre: 20A; PC & Peripherals: 20A; Pumps: 20A; Appliances/circuit: 1 or more", "type": "fact"}, {"text": "Overcurrent Protection: Overcurrent: excessive current flow due to overload or short circuit; Circuit breaker stops overcurrent; Fuse: fusible element opens when amperage too high", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-003-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Footcandle vs Lux Conversion: 1 footcandle (fc) = 10.76 lux; Lux is SI unit for illumination (lumens/m²); Footcandle is older Imperial unit", "type": "fact"}, {"text": "Lighting Level Requirements: Office/general work: 500 lux (46.5 fc); Commercial retail: 500 lux; Residential: 150-300 lux; Hallways/corridors: 150 lux; Stairways: 150-300 lux; Parking areas: 50-150 lux", "type": "fact"}, {"text": "Zonal Cavity Method: Standardized calculation method for interior lighting design; Uses room dimensions, surface reflectances, fixture data", "type": "fact"}, {"text": "Color Temperature: Warm light (2700-3000K): residential; Cool white (4000K): commercial/office; Daylight (5000-6500K): outdoor", "type": "fact"}, {"text": "Color Rendering Index (CRI): Measure of how accurately light source renders object colors; CRI 90+: excellent; CRI 70-89: average", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-004-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Noise Criteria (NC Curves): Standard reference curves for background noise levels; NC30-35: quiet office; NC40-45: normal office; NC50: retail/restaurant; Higher NC = more noise acceptable", "type": "fact"}, {"text": "Decibel (dB) Scale: Logarithmic scale for sound pressure level; 0 dB: threshold of hearing; 60 dB: normal conversation; 80 dB: loud office; 100 dB: uncomfortable; 120 dB: pain threshold", "type": "fact"}, {"text": "Reverberation Time (RT60): Time for sound to decay 60 dB after source stops; Sabine formula: RT60 = 0.161 × V / A; Where V = room volume (m³), A = total absorption (sabins); Target RT60: 0.5-1.5 sec for speech, 1.5-2.5 sec for music", "type": "fact"}, {"text": "Sound Transmission Class (STC): Rating for partition sound insulation; STC 30: normal speech audible; STC 45: loud speech barely audible; STC 60: loud speech not audible", "type": "fact"}, {"text": "Acoustic Materials: Absorption coefficients vary by frequency; 125 Hz, 250 Hz, 500 Hz, 1000 Hz, 2000 Hz, 4000 Hz standard test frequencies", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-004-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Sprinkler System Types: Wet pipe: water always in pipes, sprinklers open at activation; Dry pipe: air in pipes, water released on valve opening; Pre-action: detection system activates water valve before sprinkler opens; Deluge: all nozzles open simultaneously", "type": "fact"}, {"text": "Sprinkler Activation Temperature: Standard activation: 74°C (165°F); High-temperature rated: 93°C, 141°C available; Temperature rating marked on sprinkler bulb", "type": "fact"}, {"text": "Sprinkler Design Density: Varies by hazard classification: Light hazard 2.5 gpm/100 sf; Ordinary hazard 5-8 gpm/100 sf; Extra hazard 12-15 gpm/100 sf", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-005-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Standpipe Classes: Class I: 2.5\" outlet for professional firefighters; Class II: 1.5\" outlet with hose for occupants; Class III: combination Class I and II", "type": "fact"}, {"text": "Standpipe Installation: Vertical pipe extending through building from water supply; Connection points at each floor for firefighting water supply", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-UTIL-005-02';
